<script>
  /**
   * Meeting-order search replay for the robot rendezvous paper.
   *
   * GENERATED by Robot-Rendezvous/animation/export_site.py from
   * viewer_template.html -- edit it there, not here.  The run list comes
   * from /data/rendezvous/index.json and each run is fetched on demand.
   */
  import { onMount, onDestroy } from 'svelte';
  import { createViewer } from '$lib/rendezvous/viewer.js';

  let root;
  let viewer = null;
  let error = '';
  const BASE = '/data/rendezvous';

  // the site keeps its theme in localStorage and as a class on <html>
  function applyTheme() {
    const dark = document.documentElement.classList.contains('dark')
      || localStorage.getItem('theme') === 'dark';
    root.classList.toggle('dark', dark);
    root.classList.toggle('light', !dark);
  }

  let themeWatch;
  onMount(async () => {
    applyTheme();
    viewer = createViewer(root);
    themeWatch = new MutationObserver(() => { applyTheme(); viewer.redraw(); });
    themeWatch.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });

    const pick = root.querySelector('#run');
    const show = async (id) => {
      const r = await fetch(`${BASE}/${id}/data.json`);
      if (!r.ok) throw new Error(`${id}: ${r.status}`);
      viewer.load(await r.json());
      const u = new URL(location.href);
      u.searchParams.set('run', id);
      history.replaceState(null, '', u);           // deep-linkable
    };
    try {
      const r = await fetch(`${BASE}/index.json`);
      if (!r.ok) throw new Error(`index: ${r.status}`);
      const list = await r.json();
      pick.innerHTML = list.map((d) =>
        `<option value="${d.id}">${d.name} · ${d.algorithm} · ${d.objective}</option>`).join('');
      // ?run=<id>&view=schedule&frame=<1-based>&t=<seconds>
      const q = new URLSearchParams(location.search);
      const first = list.some((d) => d.id === q.get('run')) ? q.get('run') : list[0]?.id;
      pick.value = first;
      pick.onchange = () => show(pick.value).catch((e) => { error = e.message; });
      await show(first);
      if (q.has('frame')) viewer.setFrame(+q.get('frame') - 1);
      if (q.has('t')) viewer.setTime(q.get('t'));
      if (q.get('view') === 'schedule') viewer.setMode('schedule');
    } catch (e) {
      error = e.message;
    }
  });

  onDestroy(() => { themeWatch?.disconnect(); viewer?.destroy(); });
</script>

<svelte:head>
  <title>Robot Rendezvous Search Replay — Alaittin Kirtisoglu</title>
  <meta name="description" content="Interactive replay of the meeting-order search for the multi-place robot rendezvous problem: every accepted move, the candidates weighed, and the recharging schedule of each solution." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap">
  <link rel="stylesheet" href="/rendezvous/viewer.css">
</svelte:head>

<div class="rv-viewer" bind:this={root}>
  <header class="bar">
    <div>
      <span class="eyebrow" id="eyebrow"><a href="/research/rendezvous/">Robot rendezvous</a> · meeting-order search replay</span>
      <h1 id="title">&nbsp;</h1>
      <div class="subtitle" id="subtitle"></div>
    </div>
    <div class="pick"><label for="run">Run</label><select id="run"></select></div>
    <dl class="stats" id="stats"></dl>
  </header>

  <main>
    <section class="stage">
      <canvas id="map"></canvas>
      <div class="hint" id="hint"></div>
      <div class="tip" id="tip" hidden></div>
      <div class="legend" id="legend"></div>
    </section>

    <aside class="rail">
      <div class="card" data-show="search">
        <h2>Event</h2>
        <div class="verdict"><span class="dot" id="vdot"></span><span id="vtext">—</span></div>
        <div class="kv" id="ev"></div>
      </div>
      <div class="card" data-show="search">
        <h2>Meeting order <em id="seqNote"></em></h2>
        <div class="seq" id="seq"></div>
      </div>
      <div class="card grow" data-show="search">
        <h2>Best candidates this pass <em id="candNote"></em></h2>
        <div class="cands" id="cands"></div>
      </div>
      <div class="card" data-show="schedule">
        <h2>Tanker <em id="clock"></em></h2>
        <div class="kv" id="tank"></div>
      </div>
      <div class="card grow" data-show="schedule">
        <h2>Workers in meeting order <em>energy / D</em></h2>
        <div class="robots" id="robots"></div>
        <p class="note">The mark on each bar is θD, the energy a worker must still hold at its
          final location. The model fixes when robots arrive, not when they leave; here every
          robot leaves just in time, which costs nothing since waiting uses no energy.</p>
      </div>
    </aside>

    <section class="timeline">
      <canvas id="tl" tabindex="0" aria-label="Timeline; click or drag to scrub"></canvas>
      <div class="transport">
        <div class="seg" role="tablist" aria-label="View">
          <button id="mSearch" class="on" role="tab">Search</button>
          <button id="mSched" role="tab">Schedule</button>
        </div>
        <button class="primary" id="play">Play</button>
        <button id="prev">Back</button>
        <button id="next">Forward</button>
        <button id="toend">Jump to end</button>
        <select id="speed" aria-label="Playback speed">
          <option value="1" selected>1&times;</option>
          <option value="3">3&times;</option>
          <option value="8">8&times;</option>
        </select>
        <span class="pos" id="pos">—</span>
        <div class="toggles">
          <label data-show="search"><input type="checkbox" id="tGhost" checked> rejected candidates</label>
          <label data-show="search"><input type="checkbox" id="tPrev" checked> previous tour</label>
          <label data-show="search">y axis
            <select id="tRange">
              <option value="feasible" selected>feasible orders</option>
              <option value="all">all, log scale</option>
            </select></label>
          <label>labels
            <select id="tLab">
              <option value="off">none</option>
              <option value="robot" selected>robot id</option>
              <option value="pos">meeting position</option>
            </select></label>
        </div>
      </div>
    </section>
  </main>
</div>

{#if error}<div class="rv-error">could not load — {error}</div>{/if}

<style>
  :global(html), :global(body) { margin: 0; }
